    int i, j, k;
    float mean_value, std_dev_value;
    double sum, product, variance, correlation;

    // Calculate mean and standard deviation
    #pragma omp parallel for reduction(inscan,+: mean_value) private(mean_value)
    for (i = 0; i < m; i++) {
        mean[i] = 0.0f;
        for (j = 0; j < n; j++) {
            mean[i] += data[i][j];
        }
        mean_value /= n;
    }

    #pragma omp parallel for reduction(inscan,+: std_dev_value) private(std_dev_value)
    for (i = 0; i < m; i++) {
        std_dev[i] = 0.0f;
        for (j = 0; j < n; j++) {
            std_dev[i] += (data[i][j] - mean_value) * (data[i][j] - mean_value);
        }
        std_dev_value /= n;
    }

    // Center and reduce data
    #pragma omp parallel for reduction(inscan,+: sum) private(sum)
    for (i = 0; i < m; i++) {
        sum += data[i][0];
    }
    mean_value = sum / m;

    #pragma omp parallel for reduction(inscan,+: product) private(product)
    for (i = 0; i < m; i++) {
        product *= data[i][0];
    }
    stddev_value = sqrt(product / m);

    // Compute correlation matrix
    #pragma omp parallel for reduction(inscan,+: correlation) private(correlation)
    for (i = 0; i < m; i++) {
        for (j = i; j < m; j++) {
            correlation = 0.0f;
            for (k = 0; k < n; k++) {
