        #pragma omp parallel for reduction(+:tmp)
        for (int i = 0; i < rows; i++) {
            tmp += (A[i][k] * A[i][k]);
        }

        tmp = 1/sqrt(tmp);

        #pragma omp target
        #pragma omp parallel for
        for (int i = 0; i < rows; i++) {
